// 难度滑块相关
const sliderTrack = ref(null);
const isDragging = ref(false);

// 计算难度百分比
const difficultyPercentage = computed(() => {
  return ((config.value.difficulty - 1) / 4) * 100;
});

// 当前步骤是否有效
const isCurrentStepValid = computed(() => {
  // 🌟 第 4 步 (简历上传) 永远是有效的，因为它允许被跳过（为空）
  if (currentStep.value === 3) { 
    return true; 
  }
  
  const currentKey = steps.value[currentStep.value].key;
  return !!config.value[currentKey];
});
const handleResumeStepAction = () => {
  // 如果用户输入了内容，直接执行正常的下一步逻辑并保存
  if (config.value.resumeText.trim().length > 0) {
    saveConfigToStorage();
    nextStep();
  } else {
    // 如果是空的，执行跳过逻辑
    skipResumeStep();
  }
};
// 从localStorage加载配置
const loadConfigFromStorage = () => {
  try {
    const storedConfig = localStorage.getItem(CONFIG_STORAGE_KEY);
    if (storedConfig) {
      const parsedConfig = JSON.parse(storedConfig);
      
      // 更新配置，保留有效的值
      config.value.position = parsedConfig.position || "java";
      config.value.experience = parsedConfig.experience || "junior";
      config.value.type = parsedConfig.type || "coach";
      config.value.resumeText = parsedConfig.resumeText || "";
      config.value.jobRequirements = parsedConfig.jobRequirements || "";
      config.value.difficulty = parsedConfig.difficulty || 1;
    } else {
      // 如果没有存储的配置，使用默认配置
      saveConfigToStorage();
    }
  } catch (error) {
    console.error('加载配置失败:', error);
    // 加载失败时使用默认配置
    config.value.position = "java";
    config.value.experience = "junior";
    config.value.type = "coach";
    config.value.resumeText = "";
    config.value.jobRequirements = "";
    config.value.difficulty = 1;
  }
};

// 保存配置到localStorage
const saveConfigToStorage = () => {
  try {
    localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config.value));
  } catch (error) {
    console.error('保存配置失败:', error);
  }
};

// 在组件挂载时加载配置
onMounted(() => {
  loadConfigFromStorage();
  // C端正式面试：从sessionStorage读取岗位名称，预填到配置中
  const candidateJob = sessionStorage.getItem('candidate_job');
  if (candidateJob) {
    // 尝试匹配岗位选项
    const matched = positionOptions.value.find(opt =>
      opt.title.includes(candidateJob) || candidateJob.includes(opt.title)
    );
    if (matched) {
      config.value.position = matched.value;
    }
  }
  // C端正式面试：自动设置为全真模拟模式
  if (sessionStorage.getItem('isFormalExam') === 'true') {
    config.value.type = 'exam';
  }
});

// 显示确认弹窗
const showConfirmationModal = () => {
  showModal.value = true;
};

// 关闭弹窗
const closeModal = () => {
  if (!loading.value) { // 如果正在加载则不允许关闭
    showModal.value = false;
  }
};

// 获取选项标题的辅助函数
const getPositionTitle = (value) => {
  const option = positionOptions.value.find(opt => opt.value === value);
  return option ? option.title : '';
};

const getExperienceTitle = (value) => {
  const option = experienceOptions.value.find(opt => opt.value === value);
  return option ? option.title : '';
};

const getTypeTitle = (value) => {
  const option = typeOptions.value.find(opt => opt.value === value);
  return option ? option.title : '';
};

const getDifficultyText = (value) => {
  const label = difficultyLabels.value[value - 1];
  return label ? label.text : '';
};

// 处理"我已准备好"按钮点击
// 处理"我已准备好"按钮点击
const handleReady = async () => {
  if (loading.value) return; // 防止重复点击
  
  loading.value = true;
  
  try {
    // 🔴 C端正式面试：把candidate_token传给后端，用于关联JobPosition
    const candidateToken = sessionStorage.getItem('candidate_token');
    if (candidateToken) {
      config.value.token = candidateToken;
    }
    // 将配置数据发送到后端，后端会创建面试并返回唯一ID
    const response = await createInterview(config.value);
    const interviewId = response.sessionId || response.interviewId; 
    
    console.log('获取到的面试ID:', interviewId);
    console.log("后端 /start 返回的完整数据:", response);
    
    // 1. 存入开场白文本
    const firstQuestion = response.reply_text || response.reply || response.data?.reply_text || response.data?.reply || response.question || "你好，请先做一个简单的自我介绍，并聊聊你最自豪的一次项目经历。";
    sessionStorage.setItem('currentQuestion', firstQuestion);

    // ==========================================
    // 🔴 核心修复：提取并存入开场白语音链接！
    // ==========================================
    const firstAudioUrl = response.reply_audio_url || response.data?.reply_audio_url || response.data?.reply_audio;
    if (firstAudioUrl) {
      console.log("✅ 成功提取到开场白语音链接:", firstAudioUrl);
      sessionStorage.setItem('currentAudioUrl', firstAudioUrl);
    } else {
      console.warn("⚠️ 后端没有返回开场白语音链接");
      sessionStorage.removeItem('currentAudioUrl'); // 防御性清理，防止播上一场的残留声音
    }
    sessionStorage.setItem(`interview_bootstrap_${interviewId}`, JSON.stringify({
      question: firstQuestion,
      audioUrl: firstAudioUrl || '',
      questionNumber: response.question_number || 1,
      totalQuestions: response.total_questions || 7
    }));
    // ==========================================
    // 🌟 新增：把选好的难度同步给 Start.vue
    // ==========================================
    const diffLevel = config.value.difficulty;
    const diffLabel = getDifficultyText(diffLevel) || "中等"; // 用你现成的辅助函数拿文字
    
    // 存入 sessionStorage，Start.vue 的 onMounted 会自动读取它
    sessionStorage.setItem('interview_difficulty', JSON.stringify({
      level: diffLevel,
      label: diffLabel
    }));
    // ==========================================
    // 跳转到面试页面，携带从后端获取的ID
    router.push(`/interview/session/${interviewId}`);
  } catch (error) {
    console.error('创建面试失败:', error);
    alert('创建面试失败，请重试');
  } finally {
    loading.value = false;
    // 关闭弹窗
    closeModal();
  }
};

// 选择操作
const selectPosition = (value) => {
  config.value.position = value;
  saveConfigToStorage(); // 保存到本地存储
  if (currentStep.value < steps.value.length - 1) {
    currentStep.value++;
  }
};

const selectExperience = (value) => {
  config.value.experience = value;
  saveConfigToStorage(); // 保存到本地存储
  if (currentStep.value < steps.value.length - 1) {
    currentStep.value++;
  }
};

const selectType = (value) => {
  config.value.type = value;
  saveConfigToStorage(); // 保存到本地存储
  if (currentStep.value < steps.value.length - 1) {
    currentStep.value++;
  }
};

// 跳过简历步骤
const skipResumeStep = () => {
  // 清空简历相关信息
  config.value.resumeText = "";
  config.value.jobRequirements = "";
  saveConfigToStorage();
  currentStep.value++;
};

const selectDifficulty = (value) => {
  config.value.difficulty = value;
  saveConfigToStorage(); // 保存到本地存储
};

// 步骤导航
const nextStep = () => {
  if (currentStep.value < steps.value.length - 1) {
    currentStep.value++;
  }
};

const prevStep = () => {
  if (currentStep.value > 0) {
    currentStep.value--;
  }
};

// 难度滑块相关函数
const startDrag = (e) => {
  e.preventDefault();
  isDragging.value = true;
  document.addEventListener("mousemove", handleDrag);
  document.addEventListener("mouseup", stopDrag);
};

const handleDrag = (e) => {
  if (!isDragging.value || !sliderTrack.value) return;
  updateDifficultyFromEvent(e);
};

const stopDrag = () => {
  isDragging.value = false;
  document.removeEventListener("mousemove", handleDrag);
  document.removeEventListener("mouseup", stopDrag);
};

const updateDifficultyFromEvent = (e) => {
  if (!sliderTrack.value) return;
  const rect = sliderTrack.value.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const percentage = Math.max(0, Math.min(100, (x / rect.width) * 100));
  const level = Math.round((percentage / 100) * 4) + 1;
  config.value.difficulty = level;
  saveConfigToStorage(); // 保存到本地存储
};

const handleTrackClick = (e) => {
  if (e.target.classList.contains("slider-handle")) return;
  updateDifficultyFromEvent(e);
};

const handleTrackMove = (e) => {
  if (!isDragging.value) return;
  updateDifficultyFromEvent(e);
};
</script>

